          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/DESIGN_MODULE_METHOD.md#Design%20Module%20Method%2F4B.%20Ontology-First%20Design%20Rule%2FTransformation%20Admission%20Completeness%20%28%60STDO-UP-016%60%29%2FAdmission%20contract%20use",
          "start_line": 908
