    },
    {
      "applies_to_keys": ["prime_semantic_atom", "design_ontology"],
      "conditions": [
        "Prime review precedes promotion."
      ],
      "exceptions": [],
      "grounding": [
        {
          "end_line": 988,
          "quote": "Prime review evaluates the complete candidate semantic-atom family and every\nproposed realization projection, not only functions, carriers, or each atom in\nisolation. The family includes every proposed identity, authority transition,\nlifecycle relation, topology, function, composition law, effect, and closure\nlaw. A function-and-carrier-only pass does not establish whole-family Prime.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/DESIGN_MODULE_METHOD.md#Design%20Module%20Method%2F4B.%20Ontology-First%20Design%20Rule%2FWhole-Family%20Prime%20Contraction",
          "start_line": 984
        }
      ],
      "key": "whole_family_prime_contraction",
      "statement": "Review all candidate identities, authority transitions, lifecycle, topology, functions, composition, effects and closure laws plus every realization projection, not functions/carriers/isolated atoms only. Before promotion ask whether operations parameterize one atom, commands are entity transitions, reads project one truth, implementations instantiate one higher-order function, independent identity/authority/effect/lifecycle/reuse/public pattern-match semantics exist, all kinds entered contraction, every unit maps to accepted atoms, and any projection adds/duplicates/reinterprets meaning or authority. Individually plausible functions are not Prime if one parameterized template with closed variants preserves meaning/authority. Visible recurrence must contract during design; later recurrence review is no substitute.",
      "uncertainty": ""
