    {
      "applies_to_keys": ["prime_semantic_atom", "design_ontology"],
      "conditions": [
        "A material semantic boundary is subject to Prime contraction."
      ],
      "exceptions": [
        "Work inside an accepted boundary cites the existing Prime basis instead of recreating it."
      ],
      "grounding": [
        {
          "end_line": 1025,
          "quote": "Contraction must preserve root authority and every retained semantic relation.\nReducing files, functions, operations, or authoring surfaces cannot compensate\nfor introducing another authority source or truth path. Prime evidence states\nthe complete candidate semantic-atom family; each atom's stable identity,\nirreducible relation, admitted domain, and falsification condition; the\nwhole-family contraction relation; retained meaning and authority before and\nafter contraction; accepted loss; and the explicit total mapping from every\nproposed realization projection to its accepted atom or atoms. Work inside an\naccepted boundary cites the existing Prime basis rather than recreating it.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/DESIGN_MODULE_METHOD.md#Design%20Module%20Method%2F4B.%20Ontology-First%20Design%20Rule%2FRecursive%20Prime%20And%20Root%20Conservation%20%28%60STDO-UP-003%60%29",
          "start_line": 1017
        }
      ],
      "key": "recursive_prime_root_conservation",
      "statement": "Contract each candidate atom and then the complete resulting family. Local irreducibility or realization conformance does not prove global Prime when identity, authority, function, lifecycle, topology, effect or projection meaning duplicates. Preserve root authority and every retained semantic relation; fewer files/functions/operations/surfaces cannot compensate for added truth paths. Evidence identifies the complete family, each stable ID/irreducible relation/domain/falsifier, family contraction, before/after retained meaning and authority, accepted loss and total projection-to-accepted-atom mapping.",
      "uncertainty": ""
    },
    {
      "applies_to_keys": ["design_ontology", "irreducible_carrier_set"],
      "conditions": [
        "A design projection is claimed."
      ],
      "exceptions": [
        "Intentional omission/flattening requires declared accepted loss and a failure condition.",
        "Implementation branches/test expectations need not be individually enumerated in Ontology if traced through requirements and accepted design."
      ],
      "grounding": [
        {
          "end_line": 1044,
          "quote": "The binding names its Ontology source and the laws preserved. Intentional\nomission or flattening declares accepted loss and a failure condition. Target\ndesign may add structural HOW, but cannot originate rival semantic meaning.\nA public operation, message, transition, carrier or effect untraceable through\naccepted design to the Ontology cannot enter the active line. Implementation\nbranches and test expectations trace to requirements plus accepted design;\nthey preserve the Ontology without needing individual enumeration in it.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/DESIGN_MODULE_METHOD.md#Design%20Module%20Method%2F4B.%20Ontology-First%20Design%20Rule%2FOntology%20Projection%20Law",
          "start_line": 1038
