      ],
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1129,
          "quote": "Review cuts, realization units, runtime modules, and work items are distinct\nboundaries. They may relate many-to-one or one-to-many and must not be forced\ninto one-to-one decomposition for administrative convenience.\n\nPrime review accounts for governance cost as well as implementation count.\nContraction is not successful when it increases authority centers, maintained\ntruth surfaces, acceptance boundaries, dependency cycles, manually reconciled\nprojections, or review burden. Evidence remains proportional to semantic\nchange and risk; this rule does not require one artifact or review per concern.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/DESIGN_MODULE_METHOD.md#Design%20Module%20Method%2F5.%20Prime%20Law%2FBoundary%20And%20Governance%20Cost%20%28%60STDO-UP-005%60%29",
          "start_line": 1121
        }
      ],
      "key": "boundary_governance_cost",
      "statement": "Review cuts, realization units, runtime modules and work items are distinct and may relate many-to-one or one-to-many; administrative convenience cannot force one-to-one decomposition. Prime review accounts for governance cost as well as counts. Increased authority centers, truth surfaces, acceptance boundaries, dependency cycles, manual projection reconciliation or review burden defeat successful contraction. Evidence remains proportional to semantic change/risk without one artifact/review per concern.",
      "uncertainty": ""
